mapper.select:
select f.*,u.user_name as userName,u.phone,u1.user_name as ordersUserName,u1.phone as ordersPhone,
       (select g.game_name from game g where g.id=f.game_id) as gameName
from fast_order f
left join tb_user u on u.user_id=f.user_id
left join tb_user u1 on u1.user_id=f.orders_user_id
where 1=1

	and u.user_id=#{userId}


	and f.status=#{status}


	and u.user_name like concat('%',#{userName},'%')


	and u.phone=#{phone}


	and f.template_type=#{templateType}

order by f.create_time desc

select *,(select g.game_name from game g where g.id=f.game_id) as gameName from fast_order f
where f.fast_order_id not in (select fast_order_id from fast_order_take where user_id=#{userId})
and f.status=1 and f.user_id != #{userId}

	and f.template_type=#{templateType}

order by f.create_time desc

select f.fast_order_id,f.game_id,f.service_type,f.sex,f.money,f.skill,f.location,f.hero,f.order_level, f.my_level,f.my_system,f.my_area,f.num,f.order_taking_time,f.remark,f.user_id,f.create_time,t.status,f.orders_user_id,f.orders_id,f.fast_money ,(select g.game_name from game g where g.id=f.game_id) as gameName from fast_order_take t left join fast_order f on f.fast_order_id=t.fast_order_id where t.user_id=#{userId}
and f.status=#{status}
order by t.create_time desc
